// One n8n item per RAG chunk, with the metadata you need for citations.
const out = [];
for (const doc of $input.all()) {
  if (doc.json.error) continue; // a file that failed (not found, too large...) is reported by the Actor and skipped here
  for (const c of doc.json.chunks ?? []) {
    out.push({ json: { text: c.text, source: doc.json.url, title: doc.json.title ?? doc.json.fileName,
      pageStart: c.pageStart, pageEnd: c.pageEnd, heading: c.heading, chunk: c.index } });
  }
}
return out;
